/**
 * The DTCG design-token compiler, byte-for-byte twin of
 * `services/langgraph/agency/design_tokens.py` (Python is the reference).
 * `tests/fixtures/dtcg-compiler.json` is generated by Python and every entry,
 * including every error (class, code, path, message), must be reproduced here;
 * see `tests/parity.test.ts`.
 *
 * Pipeline, each step fail-closed with the offending token path:
 *   READ -> VALIDATE -> RESOLVE_ALIASES -> DETECT_CYCLES -> TYPECHECK -> NORMALIZE -> GENERATE_CSS
 * An unknown `$type` is an error, never a pass-through.
 *
 * Where JS and Python differ, and what this twin does about it:
 * - Ints vs floats. Python's source hash dumps `1.0` and `1` differently. An
 *   integral `number` (or `bigint`) is an int, a non-integral one a float, and an
 *   integral float must be a `CanonicalFloat` (`@amc/canonical`). Read token files
 *   with `parseTokenJson`, not `JSON.parse`, which turns `1.0` into `1`. An
 *   integral `number` beyond 2^53 reaching the hash is refused (`TokenAmbiguityError`).
 * - Python builtin failures the reference lets escape (unhashable `unit`/`colorSpace`,
 *   `float()` overflow on huge ints, a non-object theme, a missing graph key) are
 *   `PythonRuntimeError` with Python's type name and message.
 * - Dict order. Python keeps insertion order; JS objects put integer-like keys
 *   first. The compiler sorts everywhere it matters, so this is visible only in
 *   `repr()` of an offending dict inside an error message and in which of several
 *   broken themes is reported first.
 * - `repr()` of non-printable characters uses the JS engine's Unicode tables, which
 *   can be newer than Python's for unassigned code points.
 */
export { CanonicalFloat } from '@amc/canonical';
export {
  MissingAliasError,
  TokenAmbiguityError,
  TokenCycleError,
  TokenError,
  TokenSchemaError,
  TokenTierError,
  TokenTypeError,
} from './errors';
export { PythonRuntimeError, type PythonErrorType, type PyNumber } from './python';
export { canonicalJson, parseTokenJson, sourceHash } from './json';
export { fmt, hexToColor, normalizeValue, type DtcgColor } from './normalize';
export {
  COMPILER_VERSION,
  DTCG_FORMAT,
  ResolvedToken,
  SUPPORTED_TYPES,
  TIERS,
  TIER_COMPONENT,
  TIER_PRIMITIVE,
  TIER_SEMANTIC,
  TokenGraph,
  compileCss,
  compileGraph,
  cssVariable,
  deepMerge,
  flatten,
  generateCss,
  readTokens,
  type CompileCssOptions,
  type GenerateCssOptions,
  type RawToken,
} from './compiler';
